<script>
  import { onMount } from 'svelte';
  const BASE = '/pkgmgr';
  let theme = 'dark', packages = [], loading = true, error = '', notice = null, query = '', filter = 'all', tagFilter = 'all', viewMode = 'list';
  let selectedVersions = {}, busyName = null, confirmRemoval = null, selectedNames = [], bulkBusy = false;
  let failedIcons = {}, collapsedTags = {};
  $: needle = query.trim().toLocaleLowerCase();
  $: activeCount = packages.filter(pkg => pkg.status === 'active').length;
  $: disabledCount = packages.filter(pkg => pkg.status === 'disabled').length;
  $: availableTags = ['System', 'Others', ...[...new Set(packages.flatMap(pkg => packageTags(pkg)).filter(tag => tag !== 'System' && tag !== 'Others'))].sort((a, b) => a.localeCompare(b))];
  $: visiblePackages = packages.filter(pkg => (filter === 'all' || pkg.status === filter) && (tagFilter === 'all' || packageTags(pkg).includes(tagFilter)) && (!needle || `${pkg.name} ${pkg.manifestName || ''} ${pkg.description || ''} ${pkg.author || ''}`.toLocaleLowerCase().includes(needle)));
  $: packageGroups = availableTags.map(tag => ({ label: tag, packages: visiblePackages.filter(pkg => packageTags(pkg).includes(tag)) })).filter(group => group.packages.length);
  $: selectablePackages = visiblePackages.filter(pkg => !pkg.protected);
  $: allVisibleSelected = selectablePackages.length > 0 && selectablePackages.every(pkg => selectedNames.includes(pkg.name));

  function readTheme() { theme = localStorage.getItem('think:theme') === 'light' ? 'light' : 'dark'; }
  function onStorage(event) { if (event.key === 'think:theme') readTheme(); }
  function onThemeChanged(event) { theme = event.detail === 'light' ? 'light' : 'dark'; }
  onMount(() => { readTheme(); window.addEventListener('storage', onStorage); window.addEventListener('think:theme-changed', onThemeChanged); refresh(); return () => { window.removeEventListener('storage', onStorage); window.removeEventListener('think:theme-changed', onThemeChanged); }; });
  async function json(url, options) { const response = await fetch(url, options); const data = await response.json(); if (!response.ok) throw new Error(data.error || 'The action failed.'); return data; }
  async function refresh() { loading = true; error = ''; try { packages = (await json(`${BASE}/packages`)).packages || []; selectedNames = selectedNames.filter(name => packages.some(pkg => pkg.name === name && !pkg.protected)); } catch (cause) { error = cause.message; } finally { loading = false; } }
  function packageTags(pkg) { return Array.isArray(pkg.tags) && pkg.tags.length ? pkg.tags : (pkg.protected ? ['System'] : ['Others']); }
  function setFilter(next) { filter = next; selectedNames = []; confirmRemoval = null; }
  function setTagFilter(next) { tagFilter = next; selectedNames = []; confirmRemoval = null; }
  function setViewMode(mode) { viewMode = mode; }
  function toggleTagGroup(tag) { collapsedTags = { ...collapsedTags, [tag]: !collapsedTags[tag] }; }
  function toggleSelected(name) { selectedNames = selectedNames.includes(name) ? selectedNames.filter(item => item !== name) : [...selectedNames, name]; }
  function canSelect(pkg) { return filter !== 'all' && !pkg.protected; }
  function selectFromRow(event, pkg) { if (canSelect(pkg) && !event.target.closest('button, select, option, input, label')) toggleSelected(pkg.name); }
  function selectFromKey(event, pkg) { if (canSelect(pkg) && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); toggleSelected(pkg.name); } }
  function packageInitial(pkg) { return (pkg.manifestName || pkg.name || '?').trim().charAt(0).toLocaleUpperCase() || '?'; }
  function markIconFailed(name) { failedIcons = { ...failedIcons, [name]: true }; }
  function toggleAllVisible() { const names = selectablePackages.map(pkg => pkg.name); selectedNames = allVisibleSelected ? selectedNames.filter(name => !names.includes(name)) : [...new Set([...selectedNames, ...names])]; }
  async function act(path, method, name, successText, body = null) { busyName = name; notice = null; try { await json(path, { method, headers: body ? { 'Content-Type': 'application/json' } : undefined, body: body ? JSON.stringify(body) : undefined }); notice = { kind: 'ok', text: successText }; confirmRemoval = null; selectedNames = selectedNames.filter(item => item !== name); await refresh(); } catch (cause) { notice = { kind: 'error', text: cause.message }; } finally { busyName = null; } }
  const enable = (name, version) => act(`${BASE}/packages/${encodeURIComponent(name)}/enable`, 'POST', name, `${name} was enabled.`, version ? { version } : null);
  const disable = name => act(`${BASE}/packages/${encodeURIComponent(name)}/disable`, 'POST', name, `${name} was disabled.`);
  const remove = name => act(`${BASE}/disabled/${encodeURIComponent(name)}`, 'DELETE', name, `${name} was removed.`);
  async function runBulkAction() {
    const targets = packages.filter(pkg => selectedNames.includes(pkg.name) && !pkg.protected && pkg.status === filter);
    if (!targets.length || bulkBusy) return;
    bulkBusy = true; notice = null; const failures = [];
    for (const pkg of targets) { try { const enabling = filter === 'disabled'; const version = selectedVersions[pkg.name] || pkg.versions?.at(-1)?.folder; await json(`${BASE}/packages/${encodeURIComponent(pkg.name)}/${enabling ? 'enable' : 'disable'}`, { method: 'POST', headers: enabling && version ? { 'Content-Type': 'application/json' } : undefined, body: enabling && version ? JSON.stringify({ version }) : undefined }); } catch (cause) { failures.push(`${pkg.name}: ${cause.message}`); } }
    selectedNames = []; bulkBusy = false; await refresh();
    notice = failures.length ? { kind: 'error', text: `${targets.length - failures.length} completed. ${failures.length} failed: ${failures.join(' | ')}` } : { kind: 'ok', text: `${targets.length} package${targets.length === 1 ? '' : 's'} ${filter === 'disabled' ? 'enabled' : 'disabled'}.` };
  }
</script>

<main class="app" data-theme={theme} aria-busy={loading}>
  <div class="shell">
    <header class="toolbar">
      <label class="search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"></circle><path d="m20 20-4.2-4.2"></path></svg><input type="search" bind:value={query} autocomplete="off" enterkeyhint="search" placeholder="Search packages" aria-label="Search packages" /></label>
      <label class="type-filter">
        <select bind:value={tagFilter} on:change={() => setTagFilter(tagFilter)} aria-label="Filter by package type">
          <option value="all">ALL Types</option>
          {#each availableTags as tag (tag)}<option value={tag}>{tag}</option>{/each}
        </select>
        <svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"></path></svg>
      </label>
      <div class="view-switch" aria-label="View mode">
        <button type="button" class:active={viewMode === 'grid'} aria-label="Grid view" aria-pressed={viewMode === 'grid'} on:click={() => setViewMode('grid')} title="Grid view"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="6" height="6"></rect><rect x="14" y="4" width="6" height="6"></rect><rect x="4" y="14" width="6" height="6"></rect><rect x="14" y="14" width="6" height="6"></rect></svg></button>
        <button type="button" class:active={viewMode === 'list'} aria-label="List view" aria-pressed={viewMode === 'list'} on:click={() => setViewMode('list')} title="List view"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6h11M9 12h11M9 18h11"></path><path d="M4 6h.01M4 12h.01M4 18h.01"></path></svg></button>
      </div>
    </header>
    <nav class="filters" aria-label="Package filters"><button class:on={filter === 'all'} on:click={() => setFilter('all')}>All <span>{packages.length}</span></button><button class:on={filter === 'active'} on:click={() => setFilter('active')}>Active <span>{activeCount}</span></button><button class:on={filter === 'disabled'} on:click={() => setFilter('disabled')}>Disabled <span>{disabledCount}</span></button></nav>
    {#if notice}<button class="notice {notice.kind}" on:click={() => (notice = null)}>{notice.text}</button>{/if}
    {#if loading}<p class="empty">Loading packages...</p>{:else if error}<div class="empty error"><p>{error}</p><button type="button" on:click={refresh}>Try again</button></div>{:else if visiblePackages.length === 0}<p class="empty">{needle ? 'No packages match this search.' : 'No packages in this collection.'}</p>{:else}
      <section class="package-list" class:grid-mode={viewMode === 'grid'} aria-label="Installed packages">{#each packageGroups as group (group.label)}<div class="package-group"><button class="package-group-heading" class:collapsible={filter === 'all'} on:click={() => filter === 'all' && toggleTagGroup(group.label)} aria-expanded={filter === 'all' ? !collapsedTags[group.label] : undefined}><span>{group.label}</span><span class="package-group-count">{group.packages.length}</span>{#if filter === 'all'}<span class="collapse-indicator">{collapsedTags[group.label] ? '+' : '−'}</span>{/if}</button>{#if filter !== 'all' || !collapsedTags[group.label]}<div class:package-grid={viewMode === 'grid'}>{#each group.packages as pkg (pkg.name)}<article class="package-row" class:package-card={viewMode === 'grid'} class:disabled={pkg.status === 'disabled'} class:selected={selectedNames.includes(pkg.name)} role={canSelect(pkg) ? 'button' : undefined} tabindex={canSelect(pkg) ? 0 : undefined} aria-pressed={canSelect(pkg) ? selectedNames.includes(pkg.name) : undefined} on:click={event => selectFromRow(event, pkg)} on:keydown={event => selectFromKey(event, pkg)}><div class="app-icon" aria-hidden="true">{#if pkg.icon && !failedIcons[pkg.name]}<img src={pkg.icon} alt="" on:error={() => markIconFailed(pkg.name)} />{:else}<span class="app-icon-initial">{packageInitial(pkg)}</span>{/if}</div><div class="package-info"><div class="package-name"><strong>{pkg.name}</strong><span>v{pkg.version || '-'}</span>{#if pkg.status === 'disabled'}<span>Disabled</span>{/if}</div><p title={pkg.description || 'No description provided.'}>{pkg.description || 'No description provided.'}</p><div class="package-meta"><span>{group.label}</span>{#if pkg.author}<span>by {pkg.author}</span>{/if}</div></div><div class="package-actions">{#if pkg.protected}<button class="secondary" disabled title="System package">{pkg.status === 'disabled' ? 'Enable' : 'Disable'}</button>{:else if pkg.status === 'disabled'}<div class="package-lifecycle">{#if pkg.versions?.length > 1}<select aria-label={`Version to enable for ${pkg.name}`} value={selectedVersions[pkg.name] || ''} on:change={event => (selectedVersions = { ...selectedVersions, [pkg.name]: event.currentTarget.value })}><option value="" disabled>Choose version</option>{#each pkg.versions as version}<option value={version.folder}>v{version.version || '-'}</option>{/each}</select>{/if}<button class="primary" on:click={() => enable(pkg.name, pkg.versions?.length > 1 ? selectedVersions[pkg.name] : pkg.versions?.[0]?.folder)} disabled={busyName === pkg.name || (pkg.versions?.length > 1 && !selectedVersions[pkg.name])}>Enable</button></div>{#if confirmRemoval === pkg.name}<div class="package-removal"><button class="danger" on:click={() => remove(pkg.name)}>Confirm removal</button><button class="text-button" on:click={() => (confirmRemoval = null)}>Cancel</button></div>{:else}<button class="text-button remove-button" on:click={() => (confirmRemoval = pkg.name)}>Remove</button>{/if}{:else}<button class="secondary" on:click={() => disable(pkg.name)} disabled={busyName === pkg.name}>Disable</button>{/if}</div></article>{/each}</div>{/if}</div>{/each}</section>
    {/if}
  </div>
  {#if filter !== 'all' && selectablePackages.length}<aside class="bulk-dock" aria-label="Bulk package actions"><label><input type="checkbox" checked={allVisibleSelected} on:change={toggleAllVisible} /><span>Select visible</span></label><span class="selected-count">{selectedNames.length} selected</span><button class={filter === 'active' ? 'secondary' : 'primary'} disabled={!selectedNames.length || bulkBusy} on:click={runBulkAction}>{bulkBusy ? 'Working...' : filter === 'active' ? 'Disable selected' : 'Enable selected'}</button></aside>{/if}
</main>

<style>
  @import url('https://fonts.googleapis.com/css2?family=Ubuntu:wght@300;400;500;700&family=Ubuntu+Mono:wght@400;700&display=swap');
  :global(*) { box-sizing:border-box; } :global(body) { margin:0; }
  .app[data-theme='dark'] { --bg:#111111;--surface:#181818;--surface-2:#1f1f1f;--border:rgba(255,255,255,.09);--border-hi:rgba(255,255,255,.16);--text:#f5f5f5;--muted:#888888;--accent:#f5f5f5;--on-accent:#111111; }
  .app[data-theme='light'] { --bg:#ffffff;--surface:#f5f5f5;--surface-2:#ececec;--border:rgba(0,0,0,.10);--border-hi:rgba(0,0,0,.18);--text:#1a1a1a;--muted:#666666;--accent:#111111;--on-accent:#ffffff; }
  .app { min-height:100dvh;padding:24px 24px 112px;background:var(--bg);color:var(--text);font-family:'Ubuntu',system-ui,sans-serif; } button,input,select { font:inherit; } button { cursor:pointer; } button:disabled { opacity:.4;cursor:default; } svg { fill:none;stroke:currentColor;stroke-width:1.7; }
  .shell { width:min(820px,100%);margin:auto; }.toolbar { display:flex;align-items:center;gap:8px;margin-bottom:13px; }.search { display:flex;min-width:0;flex:1;align-items:center;gap:9px;padding:0 11px;border:1px solid var(--border);border-radius:8px;background:transparent;color:var(--muted); }.search:focus-within { border-color:var(--border-hi); }.search svg,.type-filter svg,.view-switch svg { width:16px;height:16px;flex:none;fill:none;stroke:currentColor;stroke-width:1.8; }.search input { width:100%;min-width:0;padding:10px 0;border:0;outline:0;background:transparent;color:var(--text);font-size:14px; }.type-filter { position:relative;display:block;color:var(--muted); }.type-filter select { height:100%;min-height:38px;appearance:none;-webkit-appearance:none;padding:0 34px 0 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:var(--text);cursor:pointer;font-size:12px; }.type-filter svg { position:absolute;top:50%;right:10px;pointer-events:none;transform:translateY(-50%); }.type-filter select:hover,.type-filter select:focus { border-color:var(--border-hi);outline:0; }.view-switch { display:flex;flex:none;gap:3px;padding:3px;border:1px solid var(--border);border-radius:8px; }.view-switch button { display:grid;width:30px;height:30px;place-items:center;border:0;padding:0;background:transparent;color:var(--muted); }.view-switch button.active { background:var(--surface-2);color:var(--text); }.filters { display:flex;align-items:center;gap:5px;overflow-x:auto;margin-bottom:15px;border-bottom:1px solid var(--border);scrollbar-width:none; }.filters::-webkit-scrollbar { display:none; }.filters button { flex:none;padding:8px 10px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);font-size:12px;white-space:nowrap; }.filters button.on { border-bottom-color:var(--accent);color:var(--text);font-weight:500; }.filters span { margin-left:3px;font:10px 'Ubuntu Mono',monospace; }.notice { display:block;width:100%;margin:0 0 12px;padding:9px 11px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text);text-align:left;font-size:12px; }.notice.error { border-color:var(--border-hi); }
  .package-list { display:grid;gap:16px; }.package-group-heading { display:flex;width:100%;align-items:center;gap:7px;margin:0;padding:0 2px 7px;border:0;background:transparent;color:var(--text);font:500 11px 'Ubuntu Mono',monospace;text-align:left;text-transform:uppercase;letter-spacing:.06em; }.package-group-heading.collapsible { cursor:pointer; }.package-group-count { color:var(--muted);font:10px 'Ubuntu Mono',monospace; }.collapse-indicator { margin-left:auto;color:var(--muted);font-size:17px;line-height:10px; }.package-row { display:grid;grid-template-columns:34px minmax(0,1fr) auto;min-height:60px;align-items:center;column-gap:11px;margin:0 0 6px;padding:9px 10px;border:1px solid var(--border);border-radius:8px;background:var(--surface); }.package-row[role='button'] { cursor:pointer; }.package-row[role='button']:hover { background:var(--surface-2);border-color:var(--border-hi); }.package-row[role='button']:focus-visible { outline:2px solid var(--accent);outline-offset:2px; }.package-row.selected { background:var(--surface-2);border-color:var(--border-hi); }.package-row.disabled { opacity:.68; }.app-icon { display:grid;width:34px;height:34px;place-items:center;overflow:hidden;border:1px solid var(--border);border-radius:8px;color:var(--muted);background:var(--surface-2); }.app-icon img { width:100%;height:100%;object-fit:cover; }.app-icon-initial { display:grid;width:100%;height:100%;place-items:center;background:var(--surface-2);color:var(--text);font:600 15px 'Ubuntu Mono',monospace; }.package-info { min-width:0; }.package-name { display:flex;align-items:center;gap:7px;min-width:0; }.package-name strong { overflow:hidden;color:var(--text);text-overflow:ellipsis;white-space:nowrap;font-size:13px;font-weight:500; }.package-name span { flex:none;padding:0;color:var(--muted);font:10px 'Ubuntu Mono',monospace; }.package-info p { overflow:hidden;margin:3px 0 0;color:var(--muted);font-size:11px;text-overflow:ellipsis;white-space:nowrap; }.package-meta { display:flex;gap:8px;margin-top:3px;color:var(--muted);font:10px 'Ubuntu Mono',monospace; }.package-meta span + span::before { content:'·';margin-right:8px;color:var(--border-hi); }.package-actions { display:flex;min-width:0;align-items:center;justify-content:flex-end;gap:6px; }.package-lifecycle,.package-removal { display:flex;align-items:center;justify-content:flex-end;gap:6px; }.primary,.secondary,.text-button,.danger,.empty button,.bulk-dock button { min-height:30px;padding:7px 10px;border-radius:8px;font-size:11px;white-space:nowrap; }.primary { border:1px solid var(--accent);background:var(--accent);color:var(--on-accent); }.danger { border:1px solid var(--border-hi);background:transparent;color:var(--text); }.secondary,.text-button,.empty button { border:1px solid var(--border);background:transparent;color:var(--text); }.text-button { border-color:transparent;color:var(--muted); }.remove-button { padding-right:0; }.package-actions select { max-width:130px;padding:6px 8px;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--text);font-size:11px; }.package-grid { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px; }.package-card { grid-template-columns:34px minmax(0,1fr);grid-template-rows:auto auto;align-items:start;min-height:142px;margin:0;padding:13px; }.package-card .package-actions { grid-column:1 / -1;justify-content:flex-end;padding-top:10px;border-top:1px solid var(--border); }.package-card .package-info p { display:-webkit-box;min-height:30px;overflow:hidden;white-space:normal;-webkit-box-orient:vertical;-webkit-line-clamp:2; }.package-card .package-meta { overflow:hidden;white-space:nowrap;text-overflow:ellipsis; }.empty { display:flex;min-height:300px;flex-direction:column;align-items:center;justify-content:center;gap:11px;margin:0;color:var(--muted);text-align:center;font-size:13px; }.empty p { margin:0; }.empty.error { color:var(--text); }
  .bulk-dock { position:fixed;z-index:5;right:max(16px,calc((100vw - 1040px) / 2));bottom:18px;display:flex;align-items:center;gap:12px;padding:9px 10px 9px 13px;border:1px solid var(--border-hi);border-radius:10px;background:var(--surface);box-shadow:0 10px 30px rgba(0,0,0,.2);font-size:12px; }.bulk-dock label { display:flex;align-items:center;gap:6px;color:var(--muted);white-space:nowrap; }.bulk-dock input { accent-color:var(--accent); }.selected-count { color:var(--muted);white-space:nowrap; }.bulk-dock button { white-space:nowrap; }
  @media (max-width:680px) { .app { padding:14px 12px 104px; }.toolbar { flex-wrap:wrap; }.search { flex-basis:100%; }.type-filter select { min-height:36px; }.view-switch { margin-left:auto; }.package-list { gap:14px; }.package-row { grid-template-columns:32px minmax(0,1fr) auto;column-gap:9px;min-height:56px;margin:0 2px 6px;padding:8px; }.app-icon { width:32px;height:32px; }.package-info p,.package-meta { display:none; }.package-name { gap:5px; }.package-name strong { font-size:13px; }.package-actions { gap:3px; }.primary,.secondary,.text-button,.danger { min-height:32px;padding:6px 8px; }.package-lifecycle,.package-removal { gap:3px; }.package-lifecycle:has(select),.package-removal { position:absolute;right:8px;left:8px;display:flex;justify-content:flex-end;transform:translateY(43px); }.package-row:has(.package-lifecycle select),.package-row:has(.package-removal) { min-height:96px;align-items:start; }.package-actions select { flex:1;max-width:170px;min-width:0; }.remove-button { padding-right:5px; }.package-card { grid-template-columns:32px minmax(0,1fr);grid-template-rows:auto auto;margin:0;min-height:150px;padding:12px; }.package-card .package-info p,.package-card .package-meta { display:-webkit-box; }.package-card .package-meta { display:flex; }.package-card .package-actions { position:static;grid-column:1 / -1;transform:none; }.package-card:has(.package-lifecycle select),.package-card:has(.package-removal) { min-height:190px; }.bulk-dock { right:12px;bottom:max(12px,env(safe-area-inset-bottom));left:12px;justify-content:space-between;gap:8px; }.bulk-dock label span { display:none; }.selected-count { flex:1; }.bulk-dock button { padding:8px 11px; } }
  @media (max-width:440px) { .package-grid { grid-template-columns:1fr; } }
</style>
